SELECT SEQ AS seq, USER_ID AS userId, PERSON AS person, CORP_NAME AS corpName, BIZ_NUM AS bizNum, PHONE AS phone, USER_LEVEL AS userLevel, REG_DATE AS regDate, LAST_LOGIN AS lastLogin, STATUS AS status FROM USER WHERE USE_YN = 'Y' AND STATUS = '승인'
AND SEQ != #{excludeSeq}
AND SEQ LIKE CONCAT('%', #{keyword}, '%')
AND CORP_NAME LIKE CONCAT('%', #{keyword}, '%')
AND BIZ_NUM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY SEQ DESC LIMIT #{skip}, #{amount}

